     "pre_process_code": "import re
MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']

def norm_date(s):
    t = str(s or '').strip().lower()
    m = re.search(r'(\d{4})-(\d{1,2})-(\d{1,2})', t)
    if m:
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
    else:
        mo = 0
        for i, name in enumerate(MONTHS):
            if re.search(r'\b' + name[:3], t):
                mo = i + 1
                break
        nums = re.findall(r'\d+', t)
        if mo:
            y = next((int(n) for n in nums if len(n) == 4), 0)
            d = next((int(n) for n in nums if len(n) <= 2), 0)
            if not y and len(nums) >= 2:
                y = int(nums[-1])
        elif len(nums) >= 3:
            d, mo, y = int(nums[0]), int(nums[1]), int(nums[2])
        elif len(nums) == 1 and len(nums[0]) == 8:
            n = nums[0]
            d, mo, y = int(n[:2]), int(n[2:4]), int(n[4:])
        else:
            return str(s)
        if not d:
            return str(s)
    if y < 100:
        y = y + 1900 if y > 30 else y + 2000
    return '%04d-%02d-%02d' % (y, mo, d)

