     "code": {"type": "string", "default": "import datetime
import json
import re

WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']
HOLIDAYS = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
BANDS = [(1, 7, 12, 1, 'early'), (8, 45, 7, 2, 'late')]

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('cannot read now: ' + s)

def parse_holidays(values):
    out = set()
    for v in values or []:
        try:
            out.add(datetime.date.fromisoformat(str(v)[:10]))
        except ValueError:
            pass
    return out

def is_business_day(d, holidays):
    return d.weekday() < 5 and d not in holidays

def next_business_day(d, holidays, include_today=False):
    if include_today and is_business_day(d, holidays):
        return d
    d = d + datetime.timedelta(days=1)
    while not is_business_day(d, holidays):
        d = d + datetime.timedelta(days=1)
    return d

def add_business_days(d, n, holidays):
    for _ in range(int(n)):
        d = next_business_day(d, holidays)
    return d

def week_monday(d):
    return d - datetime.timedelta(days=d.weekday())

def last_business_day_of_week(d, holidays):
    day = week_monday(d) + datetime.timedelta(days=4)
    while day >= week_monday(d):
        if is_business_day(day, holidays):
            return day
        day = day - datetime.timedelta(days=1)
    return None

def spoken_date(d):
    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title() + ' ' + str(d.year)

def money(amount):
    v = round(float(amount), 2)
    return '{:,.0f}'.format(v) if v == int(v) else '{:,.2f}'.format(v)

def as_list(value):
    if isinstance(value, list):
        return value
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            return []
    if isinstance(value, dict):
        return [value]
    return value if isinstance(value, list) else []

def list_from_vars(vars, name, prefixes):
    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []
    if found:
        return found
    for prefix in prefixes:
        rows = dict()
        start = prefix + '.'
        for key, value in vars.items():
            if not str(key).startswith(start):
                continue
            rest = str(key)[len(start):]
            idx, _, field = rest.partition('.')
            if idx.isdigit():
                if field:
                    rows.setdefault(int(idx), dict())[field] = value
                else:
                    rows[int(idx)] = value
        if rows:
            return [rows[i] for i in sorted(rows)]
        whole = vars.get(prefix)
        if whole not in (None, ''):
            got = as_list(whole)
            if got:
                return got
    return []

try:
    now = parse_now(vars.get('now'))
    hol = parse_holidays(HOLIDAYS)
    today = now.date()
    items = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])
    week_end = last_business_day_of_week(today, hol)
    if week_end is None or week_end <= today:
        week_end = last_business_day_of_week(today + datetime.timedelta(days=7), hol)
    lines, ids, deadlines = [], [], []
    for n, it in enumerate(items, 1):
        if not isinstance(it, dict):
            continue
        days = int(float(it.get('days_late') or 0))
        band = next((b for b in BANDS if b[0] <= days <= b[1]), BANDS[-1])
        deadline = add_business_days(today, band[2], hol)
        a1 = min(week_end, deadline) if week_end else deadline
        typ = str(it.get('type') or '')
        if typ == 'credit_card':
            name = 'credit card ending ' + str(it.get('card_last4') or '')
            floor = it.get('minimum_payment')
        else:
            name = 'car loan' if typ == 'car_loan' else 'personal loan'
            floor = it.get('instalment_amount')
        past = float(it.get('past_due') or 0)
        fl = float(floor) if floor not in (None, '') else past
        pid = str(it.get('product_id') or '')
        ids.append(pid)
        deadlines.append((n, deadline))
        text = 'Product ' + str(n) + ': ' + name + ' (product_id ' + pid + '). Past due: ' + money(past) + ', ' + str(days) + ' days late. Band: ' + band[4] + '. Floor (lowest amount you may record): ' + money(fl) + '. Deadline (latest promise date): ' + spoken_date(deadline) + ' (' + deadline.isoformat() + '). Persuasion attempts allowed: ' + str(band[3]) + '. Attempt 1: ' + money(past) + ' (or the floor ' + money(fl) + ' if the customer already said the full amount is too much) on ' + spoken_date(a1) + ' (' + a1.isoformat() + ').'
        if band[3] >= 2:
            text += ' Attempt 2: the floor ' + money(fl) + ' on the deadline ' + spoken_date(deadline) + ' (' + deadline.isoformat() + ').'
        else:
            text += ' There is no attempt 2.'
        lines.append(text)
    last = max([dl for _, dl in deadlines] or [today])
    rows = []
    d = today
    end = max(last + datetime.timedelta(days=3), today + datetime.timedelta(days=14))
    while d <= end:
        if is_business_day(d, hol):
            ok = [str(n) for n, dl in deadlines if d <= dl]
            rows.append(d.isoformat() + ' ' + spoken_date(d) + ': business day; ' + ('within the deadline of product ' + ', '.join(ok) if ok else 'after every deadline'))
        else:
            nb = next_business_day(d, hol)
            rows.append(d.isoformat() + ' ' + spoken_date(d) + ': NOT a business day (' + ('holiday' if d.weekday() < 5 else 'weekend') + '); next business day ' + spoken_date(nb) + ' (' + nb.isoformat() + ')')
        d = d + datetime.timedelta(days=1)
    words = []
    for i, w in enumerate(WEEKDAYS):
        this_d = week_monday(today) + datetime.timedelta(days=i)
        next_d = this_d + datetime.timedelta(days=7)
        words.append('this ' + w + ' = ' + this_d.isoformat() + (' (already past)' if this_d < today else '') + ', next ' + w + ' = ' + next_d.isoformat())
    vars['facts_text'] = 'Today is ' + spoken_date(today) + ' (' + today.isoformat() + ').\n' + '\n'.join(lines) + '\nDate table (look dates up here, never compute them):\n' + '\n'.join(rows) + '\nWeekday words: ' + '; '.join(words) + '.'
    vars['product_ids_json'] = json.dumps(ids)
    vars['product_count'] = str(len(ids))
    vars['facts_state'] = 'ok' if ids else 'empty'
except Exception:
    vars['facts_text'] = 'The account details could not be read.'
    vars['product_count'] = '0'
    vars['facts_state'] = 'error'
